// Score at or above which a lead goes to Slack (0-100).
const CONFIDENCE_THRESHOLD = 85;

const FIELDS = ['firstName', 'lastName', 'email', 'company', 'companyDomain', 'title', 'linkedinUrl', 'phone', 'source'];

return $input.all().map(item => {
  const b = item.json.body || {};
  const lead = {};
  for (const k of FIELDS) {
    const v = b[k];
    lead[k] = v === undefined || v === null ? null : String(v).trim().slice(0, 500);
  }
  if (lead.email) lead.email = lead.email.toLowerCase();
  if (lead.companyDomain) lead.companyDomain = lead.companyDomain.toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '');
  return { json: { ...lead, confidence_threshold: CONFIDENCE_THRESHOLD } };
});

